const BUSINESS_START_HOUR = 10;
const BUSINESS_END_HOUR = 17;
const SLOT_DURATION_MINUTES = 60;
const DAYS_TO_CHECK = 7;
const TIMEZONE_OFFSET = '+05:00'; // Pakistan time (Asia/Karachi)

const busyEvents = $input.all()
  .filter(item => item.json && item.json.start)
  .map(item => ({
    start: new Date(item.json.start.dateTime || item.json.start.date),
    end: new Date(item.json.end.dateTime || item.json.end.date)
  }));

function isSlotFree(slotStart, slotEnd) {
  return !busyEvents.some(event =>
    (slotStart < event.end && slotEnd > event.start)
  );
}

const availableSlots = [];
const now = new Date();

for (let d = 1; d <= DAYS_TO_CHECK && availableSlots.length < 3; d++) {
  const day = new Date(now.getTime() + d * 24 * 60 * 60 * 1000);
  const year = day.getUTCFullYear();
  const month = String(day.getUTCMonth() + 1).padStart(2, '0');
  const dateNum = String(day.getUTCDate()).padStart(2, '0');

  const dayOfWeek = new Date(`${year}-${month}-${dateNum}T12:00:00${TIMEZONE_OFFSET}`).getDay();
  if (dayOfWeek === 0) continue; // Skip Sunday

  for (let hour = BUSINESS_START_HOUR; hour < BUSINESS_END_HOUR && availableSlots.length < 3; hour++) {
    const hourStr = String(hour).padStart(2, '0');
    const slotStart = new Date(`${year}-${month}-${dateNum}T${hourStr}:00:00${TIMEZONE_OFFSET}`);
    const slotEnd = new Date(slotStart.getTime() + SLOT_DURATION_MINUTES * 60 * 1000);

    if (isSlotFree(slotStart, slotEnd)) {
      availableSlots.push({
        start: slotStart.toISOString(),
        display: slotStart.toLocaleString('en-US', {
          weekday: 'long', month: 'short', day: 'numeric',
          hour: 'numeric', minute: '2-digit', hour12: true,
          timeZone: 'Asia/Karachi'
        })
      });
    }
  }
}

return [{ json: { slots: availableSlots } }];

const slots = $json.slots;

let message = "Great! Here are some available slots:\n\n";
slots.forEach((slot, index) => {
  message += `${index + 1}. ${slot.display}\n`;
});
message += "\nReply with the number of your preferred slot (e.g., \"1\") and I'll book it for you!";

return [{ json: { message, slots } }];

const messageText = $('SW-03: Extract Message Data').item.json.message_text.trim();
const selectedNumber = parseInt(messageText.match(/\d+/)?.[0]);

const pendingData = $('SW-03: Find Active Conversation').item.json.pending_data;
const slots = typeof pendingData === 'string' ? JSON.parse(pendingData) : pendingData;

if (!selectedNumber || selectedNumber < 1 || selectedNumber > slots.length) {
  return [{ json: { valid: false } }];
}

const selectedSlot = slots[selectedNumber - 1];

return [{ json: { valid: true, selectedSlot: selectedSlot.start, selectedSlotDisplay: selectedSlot.display } }];

